parameters.message:
={{ (() => {
  const item = $('If es link o zelle?').item.json;
  const getAmount = (obj) => {
    if (!obj) return 0;
    for (const k of Object.keys(obj)) {
      if (/monto|amount/i.test(k)) {
        const v = obj[k];
        if (v !== undefined && v !== null && v !== '') {
          const n = parseFloat(String(v).replace(/[^0-9.]/g, ''));
          if (!isNaN(n) && n > 0) return n;
        }
      }
    }
    return 0;
  };
  const numAmount = getAmount(item);
  const cleanAmount = numAmount > 0 ? numAmount.toFixed(2) : (item['Ultimo Monto'] || item['ultimo monto'] || '0.00');
  const cryptoAmount = numAmount > 0 ? (numAmount * 0.8).toFixed(2) : '0.00';
  const firstName = $json.First || item.Nombre || item.nombre || 'Customer';
  const checkoutUrl = $('Edit Fields').item.json.checkout_url || '#';

  return `Dear ${firstName},<br>
<br>
Your Total TV subscription EXPIRES TODAY!.<br>
<br>
Please note <strong>we no longer accept credit or debit cards</strong>. We apologize for the inconvenience. However, this change completely eliminates the 7% card processing fee.<br>
<br>
To give you more flexibility, we offer three convenient ways to complete your renewal:<br>
<br>
* <strong>Zelle</strong><br>
Simply use the banking details provided below to send your payment.<br>
* <strong>Cash App</strong><br>
Place your renewal order on our website and select Cash App at checkout.<br>
* <strong>Crypto (An even better deal! 💡)</strong><br>
Pay with USDT, BTC, etc., and save 20% on every renewal!<br>
<br>
Please let us know once you have submitted your payment so we can keep an eye on your activation.<br>
Thank you so much for your understanding and for choosing us!<br>
<br>
Best regards,<br>
<br>
The Total TV Team<br>
<br>
------------------<br>
<br>
<h3>💵 OPTION 1: Zelle</h3>
Please send <strong>$${cleanAmount}</strong> to:<br>
<strong>acalimanr@gmail.com</strong><br>
<br>
Here's the Zelle QR:<br>
<img src="https://raw.githubusercontent.com/totaltvusa/images/9f5aa94b431a2c954f99d0b9c4a58da580b05f86/Zelle%20USA.jpg" width="313" style="display: block; max-width: 100%; height: auto;" border="0" /><br>
<br>
------------------<br>
<br>
<h3>📲 OPTION 2: Pay using Cash App</h3>
If you wish to pay using Cash App, please place an order on our website <a href="http://totaltvusa.com/">totaltvusa.com</a> and select <strong>Cash App</strong> as your payment method at checkout.<br>
<em>Please note: This payment method will add a 10% payment processing fee to your order total.</em><br>
<br>
------------------<br>
<br>
<h3>💡 OPTION 3: Crypto (Save 20% on every renewal!)</h3>
<a href="${checkoutUrl}">Click here to pay $${cryptoAmount} via Crypto</a>.<br>
<br>
Alternatively, you can pay by sending <strong>$${cryptoAmount}</strong> on Bitcoin directly to our secure wallet address using your preferred crypto wallet (such as <strong>MetaMask, Coinbase</strong>, etc.), or by buying and sending Bitcoin through <strong>Cash App</strong> or <strong>PayPal</strong>:<br>
<br>
<strong>Our Bitcoin Wallet Address:</strong> <code>13w3KWDYDDV8aCq7NTRxuHQ8eb5onHQzAo</code><br>
<br>
If you are using Cash App or PayPal, here are two short 2-minute video tutorials to guide you step-by-step:<br>
* <a href="https://www.youtube.com/watch?v=uqklYk2bs1o">How to pay using Cash App</a><br>
* <a href="https://www.youtube.com/watch?v=56tarYqos7w">How to pay using PayPal</a><br>
<br>
------------------<br>
<br>
Or place a new order on our website: <a href="http://totaltvusa.com/">totaltvusa.com</a><br>
<br>
-----------<br>
Questions? <a href="https://wa.me/13059861096?text=Hello!,%20%20I%20have%20a%20question:%20">Chat with us!</a><br>
<br>
<img src="https://raw.githubusercontent.com/totaltvusa/images/9f5aa94b431a2c954f99d0b9c4a58da580b05f86/Logo_TotalTv_1" width="200" style="display: block; max-width: 100%; height: auto;" border="0" />`;
})() }}

